WITH kept_keys AS (SELECT channel, id FROM promotions INTERSECT ALL SELECT channel, id FROM promotions WHERE channel IN ('partner', 'store', 'web')), reconciled AS (SELECT s.* FROM promotions s INNER JOIN kept_keys k ON s.channel = k.channel AND s.id = k.id) SELECT DATE_TRUNC('YEAR', starts_on) AS year_start, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, MAX(discount_pct) FILTER (WHERE channel = 'store') AS store_max_discount_pct FROM reconciled GROUP BY DATE_TRUNC('YEAR', starts_on);
